<template>
  <div class="page-shell"><div class="page-heading"><div><h1>入住登记与审核</h1><p>房东实时登记承租人，承租人扫码申报，民警统一审核。</p></div><el-button v-if="['ADMIN','OWNER','TENANT'].includes(auth.role)" type="primary" @click="openRegister"><el-icon><Plus/></el-icon>{{auth.role==='OWNER'?'登记承租人':'提交入住申请'}}</el-button></div>
    <section class="panel"><div class="toolbar"><el-input v-model="query.keyword" clearable placeholder="承租人、手机号、房屋或房东" style="width:280px"/><el-select v-model="query.status" clearable placeholder="审核状态" style="width:140px"><el-option v-for="(v,k) in statuses" :key="k" :label="v" :value="k"/></el-select><el-select v-model="query.source" clearable placeholder="登记来源" style="width:140px"><el-option v-for="(v,k) in sources" :key="k" :label="v" :value="k"/></el-select><el-button @click="load"><el-icon><Search/></el-icon>查询</el-button><el-button @click="reset">重置</el-button></div>
      <div class="table-wrap"><el-table :data="page.records" v-loading="loading"><el-table-column prop="tenantName" label="承租人" min-width="100"/><el-table-column prop="phone" label="手机号" width="125"/><el-table-column prop="houseName" label="租住房屋" min-width="230"/><el-table-column prop="ownerName" label="房东" width="100"/><el-table-column prop="startDate" label="入住日期" width="110"/><el-table-column label="来源" width="100"><template #default="s">{{sources[s.row.source]}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="statusType[s.row.status]">{{statuses[s.row.status]}}</el-tag></template></el-table-column><el-table-column prop="reviewerName" label="审核人" width="100"/><el-table-column label="操作" width="170" fixed="right"><template #default="s"><el-button v-if="['ADMIN','POLICE'].includes(auth.role)&&s.row.status==='PENDING'" link type="primary" @click="openReview(s.row)">审核</el-button><el-popconfirm v-if="s.row.status==='LIVING'" title="确认办理迁出？" @confirm="moveOut(s.row.id)"><template #reference><el-button link type="warning">办理迁出</el-button></template></el-popconfirm><el-button link @click="detail=s.row;detailDialog=true">详情</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="query.pageNum" :total="page.total" layout="total,prev,pager,next" @current-change="load"/></div></div></section>
    <el-dialog v-model="registerDialog" :title="auth.role==='OWNER'?'动态登记承租人':'提交入住申请'" width="650px"><el-alert title="提交后将实时进入民警待审核列表，审核通过后房屋状态自动更新。" type="info" :closable="false" show-icon/><el-form ref="formRef" :model="form" :rules="rules" label-width="90px" style="margin-top:20px"><el-form-item label="租住房屋" prop="houseId"><el-select v-model="form.houseId" filterable style="width:100%"><el-option v-for="h in houses" :key="h.id" :label="h.label" :value="h.id"/></el-select></el-form-item><el-row :gutter="14"><el-col :span="12"><el-form-item label="承租人姓名" prop="tenantName"><el-input v-model="form.tenantName"/></el-form-item></el-col><el-col :span="12"><el-form-item label="性别"><el-select v-model="form.gender" style="width:100%"><el-option label="男" value="男"/><el-option label="女" value="女"/></el-select></el-form-item></el-col></el-row><el-row :gutter="14"><el-col :span="12"><el-form-item label="手机号" prop="phone"><el-input v-model="form.phone"/></el-form-item></el-col><el-col :span="12"><el-form-item label="身份证号" prop="idCard"><el-input v-model="form.idCard"/></el-form-item></el-col></el-row><el-form-item label="户籍地"><el-input v-model="form.hometown"/></el-form-item><el-row :gutter="14"><el-col :span="12"><el-form-item label="入住日期" prop="startDate"><el-date-picker v-model="form.startDate" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="租期结束"><el-date-picker v-model="form.endDate" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col></el-row><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="registerDialog=false">取消</el-button><el-button type="primary" @click="register">提交登记</el-button></template></el-dialog>
    <el-dialog v-model="reviewDialog" title="审核入住登记" width="480px"><el-form :model="review" label-width="80px"><el-form-item label="审核结果"><el-radio-group v-model="review.status"><el-radio value="LIVING">审核通过</el-radio><el-radio value="REJECTED">审核驳回</el-radio></el-radio-group></el-form-item><el-form-item label="审核意见"><el-input v-model="review.comment" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="reviewDialog=false">取消</el-button><el-button type="primary" @click="submitReview">确认审核</el-button></template></el-dialog>
    <el-dialog v-model="detailDialog" title="入住登记详情" width="540px"><el-descriptions :column="1" border><el-descriptions-item label="承租人">{{detail.tenantName}} / {{detail.phone}}</el-descriptions-item><el-descriptions-item label="房屋">{{detail.houseName}}</el-descriptions-item><el-descriptions-item label="租期">{{detail.startDate}} 至 {{detail.endDate||'未填写'}}</el-descriptions-item><el-descriptions-item label="审核意见">{{detail.reviewComment||'—'}}</el-descriptions-item></el-descriptions></el-dialog>
  </div>
</template>
<script setup>
import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import dayjs from'dayjs';import http from'../api/http';import{useAuthStore}from'../stores/auth';const auth=useAuthStore(),statuses={PENDING:'待审核',LIVING:'居住中',REJECTED:'已驳回',MOVED_OUT:'已迁出'},statusType={PENDING:'warning',LIVING:'success',REJECTED:'danger',MOVED_OUT:'info'},sources={OWNER:'房东登记',TENANT:'承租人申报',ADMIN:'后台录入'},query=reactive({pageNum:1,pageSize:10,keyword:'',status:'',source:''}),page=reactive({records:[],total:0}),loading=ref(false),houses=ref([]),registerDialog=ref(false),reviewDialog=ref(false),detailDialog=ref(false),detail=ref({}),reviewId=ref(null),review=reactive({status:'LIVING',comment:''}),formRef=ref(),blank=()=>({houseId:null,tenantName:auth.user?.realName||'',phone:auth.user?.phone||'',idCard:auth.user?.idCard||'',gender:'男',hometown:'',emergencyContact:'',emergencyPhone:'',startDate:dayjs().format('YYYY-MM-DD'),endDate:'',attachment:'',remark:''}),form=reactive(blank()),rules={houseId:[{required:true,message:'请选择房屋'}],tenantName:[{required:true,message:'请输入姓名'}],phone:[{required:true,message:'请输入手机号'}],idCard:[{required:true,message:'请输入身份证号'}],startDate:[{required:true,message:'请选择入住日期'}]};onMounted(async()=>{houses.value=await http.get('/houses/options');load()});async function load(){loading.value=true;try{Object.assign(page,await http.get('/tenancies',{params:query}))}finally{loading.value=false}}function reset(){Object.assign(query,{pageNum:1,pageSize:10,keyword:'',status:'',source:''});load()}function openRegister(){Object.assign(form,blank());registerDialog.value=true}async function register(){await formRef.value.validate();await http.post('/tenancies',form);ElMessage.success('登记已提交，等待民警审核');registerDialog.value=false;load()}function openReview(row){reviewId.value=row.id;review.status='LIVING';review.comment='';reviewDialog.value=true}async function submitReview(){await http.put(`/tenancies/${reviewId.value}/review`,review);ElMessage.success('审核完成');reviewDialog.value=false;load()}async function moveOut(id){await http.put(`/tenancies/${id}/move-out`,{moveOutDate:dayjs().format('YYYY-MM-DD')});ElMessage.success('已办理迁出');load()}
</script>
